mkdir -p /tmp/bot-check && cat > /tmp/bot-check/check.mjs <<'EOF'
import assert from "node:assert/strict";
import { decideWhatsApp } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/baseline-g5-1/bot.mjs";

const INBOUND = "1767272400"; // 2026-01-01T13:00:00Z
const at = (secs) => new Date((Number(INBOUND) + secs) * 1000);
const H = 3600;
const c = (over = {}) => ({ optedIn: true, lastInboundTimestamp: INBOUND, ...over });
const ok = { allowed: true, reason: null };
const no = (reason) => ({ allowed: false, reason });

const cases = [
  ["text in window, 1s after inbound", { type: "text", contact: c() }, at(1), ok],
  ["text 23h59m59s after inbound", { type: "text", contact: c() }, at(24 * H - 1), ok],
  ["text exactly 24h after inbound", { type: "text", contact: c() }, at(24 * H), no("outside_customer_service_window")],
  ["text 25h after inbound", { type: "text", contact: c() }, at(25 * H), no("outside_customer_service_window")],
  ["text, never inbound", { type: "text", contact: c({ lastInboundTimestamp: null }) }, at(0), no("outside_customer_service_window")],
  ["text, inbound missing key", { type: "text", contact: { optedIn: true } }, at(0), no("outside_customer_service_window")],
  ["text, not opted in, in window", { type: "text", contact: c({ optedIn: false }) }, at(1), no("not_opted_in")],
  ["text, optedIn truthy non-boolean", { type: "text", contact: c({ optedIn: "yes" }) }, at(1), no("not_opted_in")],
  ["template, never inbound, opted in", { type: "template", contact: c({ lastInboundTimestamp: null }) }, at(0), ok],
  ["template, 90 days after inbound, opted in", { type: "template", contact: c() }, at(90 * 24 * H), ok],
  ["template, not opted in", { type: "template", contact: c({ optedIn: false, lastInboundTimestamp: null }) }, at(0), no("not_opted_in")],
  ["template, not opted in, recent inbound", { type: "template", contact: c({ optedIn: false }) }, at(1), no("not_opted_in")],
  ["unknown type", { type: "image", contact: c() }, at(1), no("unknown_message_type")],
  ["missing type", { contact: c() }, at(1), no("unknown_message_type")],
  ["text, malformed timestamp", { type: "text", contact: c({ lastInboundTimestamp: "17672724x0" }) }, at(1), no("invalid_last_inbound_timestamp")],
  ["text, timestamp as number", { type: "text", contact: c({ lastInboundTimestamp: 1767272400 }) }, at(1), no("invalid_last_inbound_timestamp")],
  ["text, timestamp in ms (unit mix-up)", { type: "text", contact: c({ lastInboundTimestamp: "1767272400000" }) }, at(1), no("invalid_last_inbound_timestamp")],
  ["text, inbound 2 min in future (skew ok)", { type: "text", contact: c() }, at(120), ok],
  ["text, inbound 1 h in future", { type: "text", contact: c() }, at(H), no("invalid_last_inbound_timestamp")],
];

let failed = 0;
for (const [name, msg, now, want] of cases) {
  try {
    assert.deepEqual(decideWhatsApp(msg, now), want);
    console.log("ok  ", name);
  } catch (e) {
    failed++;
    console.log("FAIL", name, JSON.stringify(decideWhatsApp(msg, now)));
  }
}
assert.throws(() => decideWhatsApp({ type: "text", contact: c() }, new Date("x")), TypeError);
console.log("ok   invalid now throws TypeError");
console.log(failed === 0 ? "ALL PASSED" : `${failed} FAILED`);
process.exitCode = failed ? 1 : 0;
EOF
node /tmp/bot-check/check.mjs

